### 4.1 uvm_sequence_item

Base class for all transaction items that flow through the sequencer-driver
mechanism.

```systemverilog
class my_transaction extends uvm_sequence_item;
  `uvm_object_utils(my_transaction)

  rand bit [31:0] addr;
  rand bit [31:0] data;
  rand bit        write;
  rand int unsigned delay;

  // Response fields
  bit [31:0] rdata;
  bit        error;

  constraint c_addr { addr inside {[32'h0000_0000 : 32'h0000_FFFF]}; }
  constraint c_delay { delay inside {[0:10]}; }

  function new(string name = "my_transaction");
    super.new(name);
  endfunction

  virtual function void do_copy(uvm_object rhs);
    my_transaction rhs_;
    super.do_copy(rhs);
    $cast(rhs_, rhs);
    addr  = rhs_.addr;
    data  = rhs_.data;
    write = rhs_.write;
    delay = rhs_.delay;
    rdata = rhs_.rdata;
    error = rhs_.error;
  endfunction

  virtual function bit do_compare(uvm_object rhs, uvm_comparer comparer);
    my_transaction rhs_;
    if (!$cast(rhs_, rhs)) return 0;
    return (super.do_compare(rhs, comparer) &&
            addr  == rhs_.addr &&
            data  == rhs_.data &&
            write == rhs_.write);
  endfunction

  virtual function string convert2string();
    return $sformatf("addr=0x%08h data=0x%08h %s delay=%0d",
                     addr, data, write ? "WR" : "RD", delay);
  endfunction

  virtual function void do_print(uvm_printer printer);
    super.do_print(printer);
    printer.print_field_int("addr",  addr,  32, UVM_HEX);
    printer.pri

