  option.name = "bus_txn_cov";

  cp_opcode:  coverpoint txn.opcode;
  cp_addr:    coverpoint txn.addr[31:28];
  cp_size:    coverpoint txn.size {
    bins small  = {[1:4]};

### Two-Block Style (Recommended)

Separate the design into a sequential block (state register) and a combinational block (next-state and output logic).

```systemverilog
typedef enum logic [2:0] {
  IDLE  = 3'b000,
  START = 3'b001,
  DATA  = 3'b010,
  PARITY= 3'b011,
  STOP  = 3'b100
} uart_state_t;

uart_state_t curr_state, next_state;

// Sequential block: state register
always_ff @(posedge clk or negedge rst_n) begin
  if (!rst_n)
    curr_state <= IDLE;
  else
    curr_state <= next_state;
end

// Combinational block: next state + outputs
always_comb begin
  // Defaults (prevent latches)
  next_state = curr_state;
  tx_busy    = 1'b0;
  tx_out     = 1'b1;

  case (curr_state)
    IDLE: begin
      if (tx_start) begin
        next_state = START;
      end
    end

    START: begin
      tx_busy = 1'b1;
      tx_out  = 1'b0;   // start bit
      if (bit_tick)
        next_state = DATA;
    end

    DATA: begin
      tx_busy = 1'b1;
      tx_out  = tx_data[bit_idx];
      if (bit_tick && bit_idx == 3'd7)
        next_state = PARITY;
    end

    PARITY: begin
      tx_busy = 1'b1;
      tx_out  = parity_bit;
      if (bit_tick)
        next_state = STOP;
    end

    STOP: begin
      tx_busy = 1'b1;
      tx_out  = 1'b1;   // stop bit
      if (bit_tick)
        next_state = IDLE;
    end

    default: next_state = IDLE;
  endcase
end
```

